import { mapState } from "vuex";
import timeOptions from "@/utils/timeOptions";
import {
  commentListApi,
  commentReplyApi,
  commentVerifyApi,
  communityReplyStatusApi
} from "@/api/community";

export default {
  name: "comment",
  data() {
    return {
      options: timeOptions,
      timeVal: [],
      tableFrom: {
        page: 1,
        limit: 15,
        data: "",
        keyword: "",
        is_verify: "",
        is_reply: "",
        field_key: "",
      },
      loading: false,
      columns: [
        {
          title: "ID",
          key: "id",
          width: 80,
        },
        {
          title: "用户昵称",
          key: "author",
          minWidth: 150,
        },
        {
          title: "文章标题",
          key: "title",
          minWidth: 150,
        },
        {
          title: "评论内容",
          key: "content",
          minWidth: 200,
        },
        {
          title:'显示隐藏',
          slot:"is_show",
          minWidth:100
        },
        {
          title: "回复数",
          key: "comment_num",
          minWidth: 100,
        },
        {
          title: "点赞数",
          key: "like_num",
          minWidth: 100,
        },
        {
          title: "待审核数",
          key: "verify_count",
          minWidth: 100,
        },
        {
          title: "上级评论",
          key: "comment_reply_content",
          minWidth: 100,
        },
        {
          title: "评论时间",
          key: "add_time",
          minWidth: 150,
        },
        {
          title: "审核状态",
          slot: "is_verify",
          minWidth: 100,
        },
        {
          title: "操作",
          slot: "action",
          fixed: "right",
          width: 170,
        },
      ],
      tableList: [],
      grid: {
        xl: 7,
        lg: 10,
        md: 12,
        sm: 24,
        xs: 24,
      },
      total: 0,
      showReplyModal: false,
      replyList: [],
      replyForm: {
        page: 1,
        limit: 20,
        is_reply: 0,
        reply_id: "",
      },
      replyTotal: 0,
      replyLoading: false,
    };
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  created() {
    this.getList();
  },
  methods: {
    createTime(e) {
      this.timeVal = e;
      this.tableFrom.time = this.timeVal.join("-");
      this.tableSearchs();
    },
    // 列表
    getList() {
      this.loading = true;
      commentListApi(this.tableFrom)
        .then((res) => {
          let data = res.data;
          this.tableList = data.list;
          this.total = res.data.count;
          this.loading = false;
        })
        .catch((res) => {
          this.loading = false;
          this.$Message.error(res.msg);
        });
    },
    lookChild(row) {
      this.replyForm.reply_id = row.id;
      this.showReplyModal = true;
      this.getReplyList();
    },
    getReplyList() {
      this.replyLoading = true;
      commentListApi(this.replyForm)
        .then((res) => {
          let data = res.data;
          this.replyList = data.list;
          this.replyTotal = res.data.count;
          this.replyLoading = false;
        })
        .catch((res) => {
          this.replyLoading = false;
          this.$Message.error(res.msg);
        });
    },
    replyPageChange(val) {
      this.replyForm.page = val;
      this.getReplyList();
    },
    // 表格搜索
    tableSearchs() {
      this.tableFrom.page = 1;
      this.getList();
    },
    reset() {
      this.tableFrom.data = "";
      this.tableFrom.keyword = "";
      this.tableFrom.is_verify = "";
      this.tableFrom.page = 1;
      this.is_reply = 1;
      this.field_key = "";
      this.timeVal = [];
      this.getList();
    },
    // 回复
    reply(row) {
      this.$modalForm(commentReplyApi(row.id)).then(() => this.getList());
    },
    // 审核
    verify(row,type) {
      commentVerifyApi(row.id,{is_verify:type}).then(res=>{
         this.getList();
      }).catch((res) => {
        this.$Message.error(res.msg);
      });
    },
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `/community/comment/del/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.tableList.splice(num, 1);
          if (!this.tableList.length) {
            this.tableFrom.page =
              this.tableFrom.page == 1 ? 1 : this.tableFrom.page - 1;
          }
          this.getList();
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    pageChange(index) {
      this.tableFrom.page = index;
      this.getList();
    },
    onchangeStatus(row) {
      communityReplyStatusApi(row.id, row.is_show).then((res) => {
        this.$Message.success(res.msg);
        this.getList()
      })
      .catch((res) => {
        this.$Message.error(res.msg);
      });
    }
  },
};
